package cn.gmiya.malodylink;
import org.json.*;
import java.util.*;
import java.nio.*;
import java.io.*;
/** Read-only Slide playback data. Seconds are chart time; no game scripts execute. */
public final class GameplayChart {
 public static final class Note {public double at,x,width,end;public int dir,tail;public final List<double[]> points=new ArrayList<>();}
 public final List<Note> notes=new ArrayList<>();public int keys;public double audioStart,first,end;public String audioName="",format="MC";public boolean effects;
 private double[] speedTimes={0},speedValues={1},speedDistances={0};
 public double travel(double t){int i=Arrays.binarySearch(speedTimes,t);if(i<0)i=Math.max(0,-i-2);return speedDistances[i]+(t-speedTimes[i])*speedValues[i];}
 void speeds(JSONArray rows)throws Exception{if(rows==null||rows.length()==0)return;if(rows.length()>20000)throw new IOException("流速事件过多");TreeMap<Double,Double> map=new TreeMap<>();map.put(-3600.0,1.0);for(int i=0;i<rows.length();i++){JSONArray v=rows.getJSONArray(i);map.put(num(v.getDouble(0),-3600,36000),num(v.getDouble(1),0,32));}speedTimes=new double[map.size()];speedValues=new double[map.size()];speedDistances=new double[map.size()];int i=0;for(Map.Entry<Double,Double> e:map.entrySet()){speedTimes[i]=e.getKey();speedValues[i]=e.getValue();if(i>0)speedDistances[i]=speedDistances[i-1]+(speedTimes[i]-speedTimes[i-1])*speedValues[i-1];i++;}}
 static double num(double v,double lo,double hi)throws IOException{if(!Double.isFinite(v)||v<lo||v>hi)throw new IOException("谱面数值超出范围");return v;}
 static double beat(JSONArray b)throws Exception {if(b.length()!=3)throw new IOException("无效节拍");double den=num(b.getDouble(2),1,1000000);return num(b.getDouble(0)+b.getDouble(1)/den,-1024,4096);}
 static final class Clock {double[] beats,bpms,times;Clock(JSONArray rows)throws Exception{if(rows.length()==0||rows.length()>2048)throw new IOException("无效BPM表");TreeMap<Double,Double> map=new TreeMap<>();for(int i=0;i<rows.length();i++){JSONObject v=rows.getJSONObject(i);if(i>0&&v.optDouble("delay",0)!=0)throw new IOException("含中途停顿的谱面暂不支持动态预览");map.put(beat(v.getJSONArray("beat")),num(v.getDouble("bpm"),1,10000));}int n=map.size();beats=new double[n];bpms=new double[n];times=new double[n];int i=0;for(Map.Entry<Double,Double> e:map.entrySet()){beats[i]=e.getKey();bpms[i]=e.getValue();if(i>0)times[i]=times[i-1]+(beats[i]-beats[i-1])*60/bpms[i-1];i++;}}
 double seconds(double b){int i=Arrays.binarySearch(beats,b);if(i<0)i=Math.max(0,-i-2);return times[i]+(b-beats[i])*60/bpms[i];}}
 public static GameplayChart mc(byte[] bytes,int lanes)throws Exception{
 if(bytes.length>16777216)throw new IOException("谱面过大");JSONObject d=new JSONObject(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));if(d.getJSONObject("meta").optInt("mode",-1)!=7)throw new IOException("当前预览支持Slide谱面");
 GameplayChart g=new GameplayChart();g.keys=lanes;JSONArray rows=d.getJSONArray("note");if(rows.length()>40000)throw new IOException("音符过多");
 if(g.keys<4||g.keys>6){double w=0;for(int i=0;i<rows.length();i++)w=Math.max(w,rows.getJSONObject(i).optDouble("w",0));if(w<=0)throw new IOException("谱面键数尚未识别");g.keys=w>=57?4:w>=47?5:6;}
 Clock c=new Clock(d.getJSONArray("time"));int points=0,audios=0;
 for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);double b=beat(row.getJSONArray("beat"));if(!row.has("x")&&row.has("sound")){audios++;g.audioName=row.getString("sound");g.audioStart=c.seconds(b)+num(row.optDouble("offset",0),-3600000,3600000)/1000;continue;}
 Note n=new Note();n.at=c.seconds(b);n.end=n.at;n.x=num(row.getDouble("x"),0,255);n.width=num(row.optDouble("w",256.0/g.keys*.94),1,256);n.dir=row.optInt("dir");JSONArray seg=row.optJSONArray("seg");if(seg!=null){if(seg.length()>1024)throw new IOException("滑键分段过多");for(int j=0;j<seg.length();j++){JSONObject s=seg.getJSONObject(j);double at=c.seconds(b+beat(s.getJSONArray("beat")));if(at<n.at-.02)throw new IOException("滑键时间无效");n.points.add(new double[]{at,num(n.x+s.optDouble("x",0),0,255)});n.tail=s.optInt("dir");}n.points.sort(Comparator.comparingDouble(v->v[0]));if(!n.points.isEmpty())n.end=n.points.get(n.points.size()-1)[0];points+=n.points.size();if(points>100000)throw new IOException("滑键分段过多");}g.notes.add(n);}
 if(audios>1)throw new IOException("多音轨谱面暂不支持动态预览");g.effects=false;JSONArray es=d.optJSONArray("effect"),ss=new JSONArray();if(es!=null){TreeMap<Double,JSONObject> events=new TreeMap<>();for(int i=0;i<es.length();i++){JSONObject e=es.getJSONObject(i);if(e.has("hs")||e.has("scroll")){double t=c.seconds(beat(e.getJSONArray("beat")));JSONObject state=events.get(t);if(state==null){state=new JSONObject();events.put(t,state);}for(String k:new String[]{"hs","scroll"})if(e.has(k))state.put(k,e.getDouble(k));}else g.effects=true;}double hs=1,scroll=1;for(Map.Entry<Double,JSONObject> event:events.entrySet()){JSONObject e=event.getValue();hs=e.optDouble("hs",hs);scroll=e.optDouble("scroll",scroll);ss.put(new JSONArray().put(event.getKey()).put(num(hs*scroll,0,32)));}}g.speeds(ss);g.finish();return g;
 }
 public static GameplayChart normalized(JSONObject d)throws Exception{GameplayChart g=new GameplayChart();g.keys=d.getInt("keys");if(g.keys<4||g.keys>6)throw new IOException("无效键数");g.audioStart=num(d.getDouble("audio_start"),-3600,3600);g.format=d.optString("format","MC");g.effects=d.optBoolean("effects");g.speeds(d.optJSONArray("scroll"));JSONArray ns=d.getJSONArray("notes");if(ns.length()>40000)throw new IOException("音符过多");int total=0;for(int i=0;i<ns.length();i++){JSONArray v=ns.getJSONArray(i);Note n=new Note();n.at=num(v.getDouble(0),-3600,36000);n.x=num(v.getDouble(1),0,255);n.width=num(v.getDouble(2),1,256);n.dir=v.getInt(3);n.tail=v.getInt(4);n.end=n.at;JSONArray ps=v.getJSONArray(5);total+=ps.length();if(total>100000)throw new IOException("分段过多");for(int j=0;j<ps.length();j++){JSONArray p=ps.getJSONArray(j);double t=num(p.getDouble(0),n.end,36000);n.points.add(new double[]{t,num(p.getDouble(1),0,255)});n.end=t;}g.notes.add(n);}g.finish();return g;}
 void finish()throws IOException{if(notes.isEmpty())throw new IOException("没有可预览音符");notes.sort(Comparator.comparingDouble(n->n.at));first=Math.min(0,Math.min(audioStart,notes.get(0).at-2));end=0;for(Note n:notes)end=Math.max(end,n.end);end+=2;if(end-first>3600)throw new IOException("谱面时长超过一小时");}
 public static GameplayChart imd(byte[] data,int keys)throws Exception {
 if(keys<4||keys>6||data.length<26||data.length>16777216)throw new IOException("无效IMD");ByteBuffer b=ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);int count=b.getInt(4);if(count<1||count>100000||8L+count*12+6>data.length)throw new IOException("无效IMD头");int offset=8+count*12;b.position(offset);if((b.get()&255)!=3||(b.get()&255)!=3)throw new IOException("无效IMD标记");int records=b.getInt();if(records<1||records>100000||offset+6L+records*11!=data.length)throw new IOException("无效IMD记录");GameplayChart g=new GameplayChart();g.keys=keys;g.format="IMD";Note active=null;
 for(int i=0;i<records;i++){int kind=b.get()&255;b.get();double t=Integer.toUnsignedLong(b.getInt())/1000.0;int lane=b.get()&255,value=b.getInt();if(lane>=keys)throw new IOException("无效IMD轨道");double x=(lane+.5)*256/keys;
 if(kind==0||kind==1||kind==2||kind==0x61||kind==0x62){if(active!=null)throw new IOException("未结束滑键");Note n=new Note();n.at=n.end=t;n.x=x;n.width=256.0/keys*.94;
 if(kind==0){g.notes.add(n);}else if(kind==1){n.dir=value>0?2:8;g.notes.add(n);}else if(kind==2){if(value<0)throw new IOException("无效长按");n.end=t+value/1000.0;n.points.add(new double[]{n.end,x});g.notes.add(n);}else{active=n;if(kind==0x61)active.points.add(new double[]{t,num((lane+value+.5)*256/keys,0,255)});}}
 else if(kind==0x21||kind==0x22||kind==0xa1||kind==0xa2){if(active==null||t<active.at)throw new IOException("无效滑键");active.points.add(new double[]{t,x});active.end=t;if(kind==0x21||kind==0xa1){active.points.add(new double[]{t,num((lane+value+.5)*256/keys,0,255)});active.tail=value>0?2:8;}else if(kind==0xa2){if(value<0)throw new IOException("无效长按");active.end=t+value/1000.0;active.points.add(new double[]{active.end,x});}if(kind==0xa1||kind==0xa2){g.notes.add(active);active=null;}}else throw new IOException("不支持的IMD记录");}
 if(active!=null)throw new IOException("未结束滑键");g.finish();return g;
 }
}
